// Shared conformance suite "audit" (v1.5.0), generated by the Python
// reference (genesismesh/conformance/generate_vectors.py audit) and copied
// unchanged. This SDK runs the vectors of what it verifies: the signed forms
// of the new records, the NA key history, the keys valid at a time, and a
// decision judged at its own time. Audit packs, evidence exports, anchors and
// the completeness check are verified by the core and genesis-mesh-verify.

type auditVector struct {
	ID          string                     `json:"id"`
	Kind        string                     `json:"kind"`
	Description string                     `json:"description"`
	Model       string                     `json:"model"`
	Record      json.RawMessage            `json:"record"`
	Input       map[string]json.RawMessage `json:"input"`
	Expected    json.RawMessage            `json:"expected"`
}

var auditKindsNotRun = map[string]bool{"pack": true, "verify_export": true, "verify_anchors": true, "completeness": true}

func loadAuditVectors(t *testing.T) []auditVector {
	t.Helper()
	raw, err := os.ReadFile("testdata/conformance/audit.json")
	if err != nil {
		t.Fatal(err)
	}
	var suite struct {
		Suite   string        `json:"suite"`
		Vectors []auditVector `json:"vectors"`
	}
	if err := json.Unmarshal(raw, &suite); err != nil {
		t.Fatal(err)
	}
	if suite.Suite != "audit" || len(suite.Vectors) == 0 {
		t.Fatalf("unexpected suite %q with %d vectors", suite.Suite, len(suite.Vectors))
	}
	return suite.Vectors
}

func auditVectorByID(t *testing.T, id string) auditVector {
	t.Helper()
	for _, v := range loadAuditVectors(t) {
		if v.ID == id {
			return v
		}
	}
	t.Fatalf("no vector %s", id)
	return auditVector{}
}

func historyOf(t *testing.T, input map[string]json.RawMessage) *NAKeyHistory {
	t.Helper()
	res, err := VerifyKeyHistory(input["genesis"], input["successions"], text(t, input["root_public_key"]))
	if err != nil || !res.Verified {
		t.Fatalf("history: %+v %v", res, err)
	}
	return res.History
}

func isoOrNil(v *time.Time) interface{} {
	if v == nil {
		return nil
	}
	return v.UTC().Format("2006-01-02T15:04:05Z")
}

func keyDicts(h *NAKeyHistory) []interface{} {
	out := []interface{}{}
	if h == nil {
		return out
	}
	for _, k := range h.Keys {
		var id interface{}
		if k.KeyID != "" {
			id = k.KeyID
		}
		out = append(out, map[string]interface{}{
			"key_sequence": k.KeySequence, "key_id": id, "public_key": k.PublicKey,
			"valid_from": isoOrNil(k.ValidFrom), "succeeded_at": isoOrNil(k.SucceededAt),
			"valid_to": isoOrNil(k.ValidTo), "valid_to_enforced": k.ValidToEnforced,
		})
	}
	return out
}

func TestConformanceAuditVectors(t *testing.T) {
	kinds := map[string]int{}
	for _, v := range loadAuditVectors(t) {
		v := v
		kinds[v.Kind]++
		if auditKindsNotRun[v.Kind] {
			continue
		}
		t.Run(v.ID, func(t *testing.T) {
			var got interface{}
			switch v.Kind {
			case "canonical_form":
				record, err := decodeObject(v.Record, "record")
				if err != nil {
					t.Fatal(err)
				}
				c, err := receivedCanonical(v.Model, record)
				if err != nil {
					t.Fatal(err)
				}
				got = map[string]interface{}{"canonical": c, "digest": sha256Hex(c)}
			case "key_history":
				res, err := VerifyKeyHistory(v.Input["genesis"], v.Input["successions"], text(t, v.Input["root_public_key"]))
				if err != nil {
					t.Fatal(err)
				}
				failures := []interface{}{}
				if !res.Verified {
					failures = append(failures, map[string]interface{}{"key_sequence": res.KeySequence, "reason": res.Reason})
				}
				got = map[string]interface{}{"verified": res.Verified, "failures": failures, "keys": keyDicts(res.History)}
			case "key_at":
				at, err := ParseTimestamp(text(t, v.Input["at"]))
				if err != nil {
					t.Fatal(err)
				}
				got = map[string]interface{}{"keys": historyOf(t, v.Input).KeysAt(at)}
			case "decision_at_record_time":
				history := historyOf(t, v.Input)
				now, _ := ParseTimestamp(text(t, v.Input["now"]))
				atRecord, err := VerifyBoundaryDecision(v.Input["decision"], DecisionVerifyOptions{KeyHistory: history, AtRecordTime: true})
				if err != nil {
					t.Fatal(err)
				}
				atNow, err := VerifyBoundaryDecision(v.Input["decision"], DecisionVerifyOptions{KeyHistory: history, Now: now})
				if err != nil {
					t.Fatal(err)
				}
				got = map[string]interface{}{"at_record_time": atRecord.Reason, "now": atNow.Reason}
			default:
				t.Fatalf("vector kind %q is neither run nor listed as not run", v.Kind)
			}
			gotRaw, _ := json.Marshal(got)
			var g, w interface{}
			_ = json.Unmarshal(gotRaw, &g)
			_ = json.Unmarshal(v.Expected, &w)
			if !reflect.DeepEqual(g, w) {
				t.Fatalf("%s\n got:  %s\n want: %s", v.Description, gotRaw, v.Expected)
			}
		})
	}
	for _, kind := range []string{"canonical_form", "key_history", "key_at", "decision_at_record_time"} {
		if kinds[kind] == 0 {
			t.Errorf("no %s vectors", kind)
		}
	}
}

// ── a succession built and signed here ─────────────────────────────────────

type successionWorld struct {
	root, na1, na2 ed25519.PrivateKey
	genesis        []byte
	successions    []byte
	effective      time.Time
	history        *NAKeyHistory
}

func seededKey(b byte) ed25519.PrivateKey {
	seed := make([]byte, ed25519.SeedSize)
	for i := range seed {
		seed[i] = b
	}
	return ed25519.NewKeyFromSeed(seed)
}

func pubOf(k ed25519.PrivateKey) string {
	return base64.StdEncoding.EncodeToString(k.Public().(ed25519.PublicKey))
}

// signedWith adds a signature by each key over the record's received form.
func signedWith(t *testing.T, model string, record object, keys ...ed25519.PrivateKey) object {
	t.Helper()
	c, err := receivedCanonical(model, record)
	if err != nil {
		t.Fatal(err)
	}
	sigs := []interface{}{}
	for i, k := range keys {
		sigs = append(sigs, map[string]interface{}{
			"key_id": []string{"root", "na-1", "na-2"}[i], "sig": base64.StdEncoding.EncodeToString(ed25519.Sign(k, []byte(c))),
		})
	}
	record["signatures"] = sigs
	return record
}

func mustJSON(t *testing.T, v interface{}) []byte {
	t.Helper()
	raw, err := json.Marshal(v)
	if err != nil {
		t.Fatal(err)
	}
	return raw
}

// newSuccessionWorld: the genesis key na-1, succeeded by na-2 on 2026-03-01.
func newSuccessionWorld(t *testing.T) successionWorld {
	t.Helper()
	w := successionWorld{root: seededKey(0x71), na1: seededKey(0x72), na2: seededKey(0x73)}
	w.effective = time.Date(2026, 3, 1, 0, 0, 0, 0, time.UTC)
	genesis := signedWith(t, "GenesisBlock", object{
		"network_name": "sovereign-s", "network_version": "v1", "root_public_key": pubOf(w.root),
		"network_authority": map[string]interface{}{
			"public_key": pubOf(w.na1), "valid_from": "2026-01-01T00:00:00Z", "valid_to": "2026-04-01T00:00:00Z",
		},
		"allowed_crypto_suites": []interface{}{"ed25519", "x25519"}, "allowed_transports": []interface{}{"quic", "wireguard"},
		"policy_manifest": map[string]interface{}{"hash": "sha256:test", "url": nil}, "bootstrap_anchors": []interface{}{},
	}, w.root)
	succession := signedWith(t, "KeySuccessionRecord", object{
		"succession_id": "00000000-0000-4000-8000-000000000001", "sovereign_id": "sovereign-s", "key_sequence": 2,
		"previous_key_id": "na-1", "previous_public_key": pubOf(w.na1), "new_key_id": "na-2",
		"new_public_key": pubOf(w.na2), "effective_at": "2026-03-01T00:00:00Z", "new_valid_to": "2028-03-01T00:00:00Z",
		"issued_at": "2026-02-20T00:00:00Z",
	}, w.root, w.na1)
	w.genesis = mustJSON(t, genesis)
	w.successions = mustJSON(t, []interface{}{succession})
	res, err := VerifyKeyHistory(w.genesis, w.successions, pubOf(w.root))
	if err != nil || !res.Verified {
		t.Fatalf("history: %+v %v", res, err)
	}
	w.history = res.History
	return w
}

// decisionAt is the audit suite's decision, made at madeAt and signed by key.
func decisionAt(t *testing.T, madeAt time.Time, key ed25519.PrivateKey) []byte {
	t.Helper()
	d := withValue(t, auditVectorByID(t, "decision-at-record-time").Input["decision"], "decision_made_at",
		madeAt.Format("2006-01-02T15:04:05Z"))
	d["decision_valid_until"] = madeAt.Add(5 * time.Minute).Format("2006-01-02T15:04:05Z")
	return resigned(t, d, key, decisionOmittedWhenAbsent...)
}

func TestDecisionsSignedBeforeAndAfterASuccession(t *testing.T) {
	w := newSuccessionWorld(t)
	cases := []struct {
		name   string
		madeAt time.Time
		key    ed25519.PrivateKey
		want   string
	}{
		{"old key before the succession", w.effective.Add(-time.Hour), w.na1, "authorized"},
		{"new key before the succession", w.effective.Add(-time.Hour), w.na2, "na_key_not_valid_at_time"},
		{"new key when it takes effect", w.effective, w.na2, "authorized"},
		{"old key during the hand-over", w.effective.Add(299 * time.Second), w.na1, "authorized"},
		{"old key at the end of the hand-over", w.effective.Add(SuccessionHandover), w.na1, "na_key_not_valid_at_time"},
		{"old key long after", w.effective.Add(30 * 24 * time.Hour), w.na1, "na_key_not_valid_at_time"},
		{"new key long after", w.effective.Add(30 * 24 * time.Hour), w.na2, "authorized"},
		{"new key after its valid_to", time.Date(2028, 3, 1, 0, 0, 0, 0, time.UTC), w.na2, "na_key_not_valid_at_time"},
		{"the root key", w.effective, w.root, "invalid_signature"},
	}
	for _, c := range cases {
		raw := decisionAt(t, c.madeAt, c.key)
		got, err := VerifyBoundaryDecision(raw, DecisionVerifyOptions{KeyHistory: w.history, Now: c.madeAt.Add(time.Minute)})
		if err != nil || got.Reason != c.want {
			t.Errorf("%s: %+v %v, want %s", c.name, got, err, c.want)
		}
		// Judged at its own time, years later, the same outcome.
		got, err = VerifyBoundaryDecision(raw, DecisionVerifyOptions{KeyHistory: w.history, AtRecordTime: true,
			Now: c.madeAt.Add(5 * 365 * 24 * time.Hour)})
		if err != nil || got.Reason != c.want {
			t.Errorf("%s at record time: %+v %v, want %s", c.name, got, err, c.want)
		}
	}
}

func TestWithoutAKeyHistoryDecisionsVerifyAsBefore(t *testing.T) {
	w := newSuccessionWorld(t)
	// A plain key list is valid at every time: no window, no new reason.
	madeAt := w.effective.Add(-time.Hour)
	raw := decisionAt(t, madeAt, w.na2)
	now := madeAt.Add(time.Minute)
	got, err := VerifyBoundaryDecision(raw, DecisionVerifyOptions{
		OperatorPublicKeys: []string{pubOf(w.na1), pubOf(w.na2)}, Now: now,
	})
	if err != nil || got.Reason != "authorized" {
		t.Errorf("plain keys: %+v %v", got, err)
	}
	got, err = VerifyBoundaryDecision(raw, DecisionVerifyOptions{OperatorPublicKeys: []string{pubOf(w.na1)}, Now: now})
	if err != nil || got.Reason != "invalid_signature" {
		t.Errorf("another key: %+v %v", got, err)
	}
	// NAKeysValidAlways reads a list as before.
	got, err = VerifyBoundaryDecision(raw, DecisionVerifyOptions{KeyHistory: NAKeysValidAlways([]string{pubOf(w.na2)}), Now: now})
	if err != nil || got.Reason != "authorized" {
		t.Errorf("keys valid always: %+v %v", got, err)
	}
	if _, err := VerifyBoundaryDecision(raw, DecisionVerifyOptions{OperatorPublicKeys: []string{pubOf(w.na1)}, KeyHistory: w.history}); err == nil {
		t.Error("keys and a history were both accepted")
	}
	// Expired now, valid when made.
	expired, err := VerifyBoundaryDecision(raw, DecisionVerifyOptions{OperatorPublicKeys: []string{pubOf(w.na2)}, Now: madeAt.Add(time.Hour)})
	if err != nil || expired.Reason != "decision_expired" {
		t.Errorf("expired: %+v %v", expired, err)
	}
	atRecord, err := VerifyBoundaryDecision(raw, DecisionVerifyOptions{OperatorPublicKeys: []string{pubOf(w.na2)}, AtRecordTime: true})
	if err != nil || atRecord.Reason != "authorized" {
		t.Errorf("at record time: %+v %v", atRecord, err)
	}
}

func TestAgreementsAreCheckedWithTheKeyValidWhenEstablished(t *testing.T) {
	v := interopVector(t, "agr-001")
	offererKeys := strings_(t, v.Input["offerer_public_keys"])
	responderKeys := strings_(t, v.Input["responder_public_keys"])
	offerer := conformanceKey(t, offererKeys)
	if pubOf(offerer) != offererKeys[0] {
		t.Fatal("unexpected offerer key")
	}
	// The offerer's history: its agreement key is the genesis key, succeeded on 2026-03-01.
	root, next := seededKey(0x74), seededKey(0x75)
	genesis := signedWith(t, "GenesisBlock", object{
		"network_name": "offerer", "network_version": "v1", "root_public_key": pubOf(root),
		"network_authority": map[string]interface{}{
			"public_key": pubOf(offerer), "valid_from": "2026-01-01T00:00:00Z", "valid_to": "2026-04-01T00:00:00Z",
		},
		"policy_manifest": map[string]interface{}{"hash": "sha256:test", "url": nil},
	}, root)
	succession := signedWith(t, "KeySuccessionRecord", object{
		"succession_id": "s-1", "sovereign_id": "offerer", "key_sequence": 2, "previous_key_id": "na-1",
		"previous_public_key": pubOf(offerer), "new_key_id": "na-2", "new_public_key": pubOf(next),
		"effective_at": "2026-03-01T00:00:00Z", "new_valid_to": "2028-03-01T00:00:00Z", "issued_at": "2026-02-20T00:00:00Z",
	}, root, offerer)
	res, err := VerifyKeyHistory(mustJSON(t, genesis), mustJSON(t, []interface{}{succession}), pubOf(root))
	if err != nil || !res.Verified {
		t.Fatalf("history: %+v %v", res, err)
	}
	for established, want := range map[string]string{
		"2026-02-28T23:59:59Z": "accepted",
		"2026-03-01T00:04:59Z": "accepted",
		"2026-03-01T00:05:00Z": "invalid_offerer_signature",
	} {
		// established_at is outside the signed form: no re-signing needed.
		raw := mustJSON(t, withValue(t, v.Input["agreement"], "established_at", established))
		got, err := VerifyAgreementWithKeyHistory(raw, res.History, NAKeysValidAlways(responderKeys), "")
		if err != nil || got.Reason != want {
			t.Errorf("established %s: %+v %v, want %s", established, got, err, want)
		}
		// Without a history the same agreement verifies as before.
		plain, err := VerifyAgreement(raw, offererKeys, responderKeys, "")
		if err != nil || plain.Reason != "accepted" {
			t.Errorf("established %s, plain keys: %+v %v", established, plain, err)
		}
	}
	if _, err := VerifyAgreementWithKeyHistory(v.Input["agreement"], res.History, nil, ""); err == nil {
		t.Error("a missing history was accepted")
	}
}

func TestKeyHistoryFromTheNAResponse(t *testing.T) {
	w := newSuccessionWorld(t)
	var genesis, successions interface{}
	_ = json.Unmarshal(w.genesis, &genesis)
	_ = json.Unmarshal(w.successions, &successions)
	body := mustJSON(t, map[string]interface{}{
		"sovereign_id": "sovereign-s", "root_public_key": "not trusted", "handover_seconds": 300,
		"genesis": genesis, "successions": successions, "keys": []interface{}{}, "signing_key_sequence": 2,
	})
	res, err := VerifyKeyHistoryResponse(body, pubOf(w.root))
	if err != nil || !res.Verified || !reflect.DeepEqual(res.History.AllKeys(), []string{pubOf(w.na1), pubOf(w.na2)}) {
		t.Fatalf("response: %+v %v", res, err)
	}
	// Another root key: the history proves nothing.
	res, err = VerifyKeyHistoryResponse(body, pubOf(w.na1))
	if err != nil || res.Verified || res.Reason != "genesis_root_mismatch" || res.History != nil {
		t.Fatalf("another root: %+v %v", res, err)
	}
	if _, err := VerifyKeyHistory(w.genesis, w.successions, ""); err == nil {
		t.Error("no root key was accepted")
	}
}

func TestASuccessionMissingItsIDIsNotInCanonicalForm(t *testing.T) {
	// The reference gives it a fresh succession_id and refuses the form.
	w := newSuccessionWorld(t)
	var list []map[string]interface{}
	_ = json.Unmarshal(w.successions, &list)
	record := object(list[0])
	delete(record, "succession_id")
	signed := signedWith(t, "KeySuccessionRecord", record, w.root, w.na1)
	res, err := VerifyKeyHistory(w.genesis, mustJSON(t, []interface{}{signed}), pubOf(w.root))
	if err != nil || res.Reason != "non_canonical_form" || res.KeySequence != 2 {
		t.Fatalf("signed without an id: %+v %v", res, err)
	}
	signed["key_sequence"] = 3
	res, err = VerifyKeyHistory(w.genesis, mustJSON(t, []interface{}{signed}), pubOf(w.root))
	if err != nil || res.Reason != "invalid_signature" || res.KeySequence != 3 {
		t.Fatalf("changed after signing: %+v %v", res, err)
	}
}
